def gen(rng):
    def fmt(a):
        return str(len(a)) + '\n' + ' '.join(map(str, a))
    tests = [fmt([5]), fmt([0]), fmt([3, 3]), fmt([1, 2]), fmt([2, 1]), fmt([0, 0, 0, 1]), fmt([10**9, 0]),
             fmt([10**9, 10**9, 10**9 - 1]), fmt([4, 4, 9, 9]), fmt([1, 2, 3, 4, 5]), fmt([5, 4, 3, 2, 1])]
    for n in (3, 4, 6, 10, 20, 40):
        for _ in range(2):
            hi = rng.choice([2, 5, 20, 10**9])
            tests.append(fmt([rng.randint(0, hi) for _ in range(n)]))
    tests.append(fmt([rng.randint(0, 10**9) for _ in range(100000)]))
    tests.append(fmt([rng.randint(0, 3) for _ in range(100000)]))
    tests.append(fmt(list(range(100000))))
    tests.append(fmt(list(range(100000, 0, -1))))
    tests.append(fmt([7] * 99999 + [3]))
    return tests
